package reqmap

import (
	"encoding/json"
	"os"
	"slices"
	"testing"
)

// D-192: hactl matches an entity glob as Home Assistant does. The vectors
// are Home Assistant's own answers: generated by
// homeassistant.helpers.entityfilter.generate_filter in the HA image the rig
// runs (the generator line in the file names the version).
func TestEntityGlobsMatchAsHomeAssistant(t *testing.T) {
	raw, err := os.ReadFile("../../../testdata/policy/services/entity_globs.json")
	if err != nil {
		t.Fatal(err)
	}
	var v struct {
		Generator string   `json:"generator"`
		IDs       []string `json:"ids"`
		Cases     []struct {
			Glob    string   `json:"glob"`
			Matches []string `json:"matches"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	if len(v.Cases) < 40 {
		t.Fatalf("only %d glob vectors", len(v.Cases))
	}
	for _, c := range v.Cases {
		var got []string
		for _, id := range v.IDs {
			m, ok := fnmatchCase(c.Glob, id)
			if !ok {
				t.Errorf("glob %q: hactl cannot read it, Home Assistant did", c.Glob)
				break
			}
			if m {
				got = append(got, id)
			}
		}
		if !slices.Equal(got, c.Matches) && (len(got) != 0 || len(c.Matches) != 0) {
			t.Errorf("glob %q matches %v, Home Assistant matches %v", c.Glob, got, c.Matches)
		}
	}
}
